const COMP={run:{g:'cardio',l:'2-mile run',t:'time',mx:50,mn:35},hamr:{g:'cardio',l:'20 m HAMR (shuttles)',t:'n',mx:50,mn:35},pu:{g:'str',l:'Push-ups (1 min)',t:'n',mx:15,mn:2.5},hr:{g:'str',l:'Hand-release push-ups (2 min)',t:'n',mx:15,mn:2.5},su:{g:'core',l:'Sit-ups (1 min)',t:'n',mx:15,mn:2.5},clrc:{g:'core',l:'Cross-leg reverse crunch (2 min)',t:'n',mx:15,mn:2.5},pl:{g:'core',l:'Forearm plank',t:'time',mx:15,mn:2.5}};
const tfmt=s=>`${Math.floor(s/60)}:${pad(Math.round(s)%60)}`,tparse=v=>{v=String(v).trim();if(!v)return NaN;if(v.includes(':')){const[a,b]=v.split(':');return(+a)*60+(+b||0)}return(+v)*60};
const pftStd=id=>{const p=S.pft||{},c=OFF[id].v[p.sex||'M'][p.age||0];return[c[c.length-1],c[0]]};
const cv=(id,x)=>COMP[id].t==='time'?tfmt(x):String(x);
function pftRead(){const p=S.pft=S.pft||{};p.v=p.v||{};for(const id in COMP){const v=$('#pf-v-'+id);if(v&&v.value!==undefined)p.v[id]=v.value}const w=$('#pf-w'),h=$('#pf-h');if(w&&w.value!==undefined){p.w=w.value;p.h=h.value}}
function pftOne(id,x){const p=S.pft||{},d=OFF[id],c=d.v[p.sex||'M'][p.age||0];let i=-1;for(let k=0;k<c.length;k++){if(id==='run'?x<=c[k]:x>=c[k]){i=k;break}}return i<0?{p:0,ok:false}:{p:d.p[i],ok:true}}
const WH=[[.49,20],[.50,19],[.51,18],[.52,17],[.53,16],[.54,15],[.55,12.5],[.56,10],[.57,7.5],[.58,5],[.59,2.5]];
function pftCalc(){const p=S.pft||{},rows=[];let tot=0,pos=0,fail=false;for(const g of['cardio','str','core']){const id=p[g];if(!id||id==='-')continue;const raw=(p.v||{})[id],x=COMP[id].t==='time'?tparse(raw):+raw;pos+=COMP[id].mx;if(raw===''||raw==null||isNaN(x)){rows.push({l:COMP[id].l,val:'not entered',p:0,mx:COMP[id].mx,ok:null});continue}const r=pftOne(id,x);tot+=r.p;if(!r.ok)fail=true;rows.push({l:COMP[id].l,val:cv(id,x),p:r.p,mx:COMP[id].mx,ok:r.ok})}
 if(p.bc){pos+=20;const w=+p.w,h=+p.h;if(w>0&&h>0){const q=Math.floor(w/h*100+1e-9)/100;let pt=0;if(q<=.49)pt=20;else for(const[a,b]of WH)if(Math.abs(q-a)<1e-9){pt=b;break}tot+=pt;rows.push({l:'Waist-to-height ratio',val:q.toFixed(2),p:pt,mx:20,ok:null})}else rows.push({l:'Waist-to-height ratio',val:'not entered',p:0,mx:20,ok:null})}
 const all=p.cardio&&p.cardio!=='-'&&p.str&&p.str!=='-'&&p.core&&p.core!=='-'&&p.bc;return{rows,tot:Math.round(tot*10)/10,pos,fail,all,d:iso(new Date())}}
const pftRef=()=>{const p=S.pft||{},sx=p.sex||'M',ag=p.age||0,G=[['Cardio (50 points)',['run','hamr']],['Strength (15 points)',['pu','hr']],['Core (15 points)',['su','clrc','pl']]],short={run:'2-mile run (or faster)',hamr:'HAMR shuttles',pu:'Push-ups',hr:'Hand-release push-ups',su:'Sit-ups',clrc:'Cross-leg reverse crunch',pl:'Forearm plank'};
 return`<details class="card"><summary><b>Score reference</b> (${sx==='F'?'Female':'Male'}, ${AGES[ag]})</summary><p class="m"><small>The result you need for each point value. Reps and shuttles mean that many or more, run times mean that time or faster. The last row of each table is the minimum, and below it the component scores 0.</small></p>${G.map(([t,ids])=>{const same=ids.every(i=>JSON.stringify(OFF[i].p)===JSON.stringify(OFF[ids[0]].p)),sets=same?[ids]:ids.map(i=>[i]);return`<b>${t}</b>`+sets.map(s=>{const P=OFF[s[0]].p;return`<div style="overflow-x:auto"><table style="font-size:13px;width:100%"><tr><th align="left">Pts</th>${s.map(i=>`<th align="left">${short[i]}</th>`).join('')}</tr>${P.map((pt,k)=>`<tr${k===P.length-1?' style="font-weight:700"':''}><td>${pt}</td>${s.map(i=>`<td>${cv(i,OFF[i].v[sx][ag][k])}</td>`).join('')}</tr>`).join('')}</table></div>`}).join('')}).join('')}<b>Waist-to-height (20 points)</b><div style="overflow-x:auto"><table style="font-size:13px;width:100%"><tr><th align="left">Pts</th><th align="left">Ratio</th></tr>${[[20,'0.49 or less']].concat(WH.map(([a,b])=>[b,a.toFixed(2)])).sort((x,y)=>y[0]-x[0]).map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}<tr><td>0</td><td>0.60 or more</td></tr></table></div><p class="m"><small>Overall you need 75 points and the minimum on every part you test. Waist has no minimum.</small></p></details>`};
const pftHTML=()=>{const p=S.pft=S.pft||{},sx=p.sex||'M',ag=p.age||0,sel=(k,opts)=>`<select data-p="pft" data-k="${k}" style="width:100%">${opts.map(([v,t])=>`<option value="${v}" ${String(v)===String(p[k]==null?(k==='sex'?'M':k==='age'?0:'-'):p[k])?'selected':''}>${t}</option>`).join('')}</select>`,
 row=id=>{const c=COMP[id],[mn,fl]=pftStd(id),T=c.t==='time',lab=id==='run'?['Slowest pass','Full points (fastest)']:['Minimum','Full points'];return`<div class="card"><b>${c.l}</b><label class="m">Your result ${T?'(m:ss)':''}<input id="pf-v-${id}" inputmode="${T?'text':'numeric'}" value="${esc((p.v||{})[id]||'')}" placeholder="${T?'e.g. 15:30':'number'}"></label><small>${lab[0]}: ${cv(id,mn)} · ${lab[1]}: ${cv(id,fl)}</small></div>`},
 res=p.res,R=res?`<div class="card" style="border-color:#34d399"><small>RESULT</small><table>${res.rows.map(x=>`<tr><td>${esc(x.l)}</td><td>${esc(x.val)}</td><td><b>${x.p}</b> / ${x.mx}${x.ok===false?' <span style="color:var(--bad)">below minimum</span>':''}</td></tr>`).join('')}</table><p><b style="font-size:22px">${res.tot} / ${res.pos}</b> points${res.pos?` (${Math.round(res.tot/res.pos*100)}%)`:''}</p>${res.all?`<p><b>${res.fail?'Unsatisfactory (a component is below its minimum)':res.tot>90?'Excellent':res.tot>=75?'Satisfactory':'Unsatisfactory (below 75)'}</b><br><small>Categories: above 90 excellent, 75 to 89.9 satisfactory, below 75 or any minimum missed unsatisfactory (from published guidance, not from the charts).</small></p>`:'<p class="m"><small>Partial test. A composite needs all four parts (cardio, strength, core and waist), and 75 or more points with every minimum met.</small></p>'}</div>`:'';
 return`<div><button data-a="x">Close</button><h2>Mock AF PT test</h2><p class="m">Pick the parts you want to do, enter your results, then tap Calculate.</p><label class="m">Sex${sel('sex',[['M','Male'],['F','Female']])}</label><label class="m">Age group${sel('age',AGES.map((a,i)=>[i,a]))}</label>
 <label class="m">Cardio${sel('cardio',[['-','Skip'],['run','2-mile run'],['hamr','20 m HAMR']])}</label>${p.cardio&&p.cardio!=='-'?row(p.cardio):''}
 <label class="m">Strength${sel('str',[['-','Skip'],['pu','Push-ups (1 min)'],['hr','Hand-release push-ups (2 min)']])}</label>${p.str&&p.str!=='-'?row(p.str):''}
 <label class="m">Core${sel('core',[['-','Skip'],['su','Sit-ups (1 min)'],['clrc','Cross-leg reverse crunch (2 min)'],['pl','Forearm plank']])}</label>${p.core&&p.core!=='-'?row(p.core):''}
 <label class="m"><input type="checkbox" data-p="pftb" ${p.bc?'checked':''} style="width:auto;min-height:auto"> Include waist-to-height ratio (20 points)</label>${p.bc?`<div class="card"><div class="flex"><label class="m" style="flex:1">Waist<input id="pf-w" inputmode="decimal" value="${esc(p.w||'')}"></label><label class="m" style="flex:1">Height (same unit)<input id="pf-h" inputmode="decimal" value="${esc(p.h||'')}"></label></div></div>`:''}
 <button class="pri" data-a="pftcalc" style="width:100%;margin:10px 0">Calculate score</button>${R}${pftRef()}<p class="m"><small>Scores use the Final USAF PFRA Scoring Charts (effective 1 Mar 26): each result earns the points of the highest row it meets. Strength and core are worth 15 each, cardio 50 and waist 20. This is a practice tool, so use myFitness for your official score. Special-duty (AFSPECWAR/EOD) charts are not included.</small></p></div>`};
